/** A broken wheel, axle or tongue: a spare mends it; without one, a carpenter mends it half the time, anyone else a third; or the party
 * waits for a passing train to trade one. */
function brokenPart(J) {
  const k = ['wheel', 'axle', 'tongue'][rndi(0, 2)], name = `A WAGON ${k.toUpperCase()} BROKE.`;
  if (J[k] > 0) { J[k]--; return [name, 'YOU REPLACED IT WITH A SPARE.']; }
  if (rnd(1) < (J.bg === 1 ? 0.5 : 0.33)) return [name, J.bg === 1 ? 'THE CARPENTER MENDED IT.' : 'YOU MANAGED TO MEND IT.'];
  const n = rndi(3, 6), f = Math.min(J.food, 40); J.food -= f; const d = loseDays(J, n);
  return [name, `YOU WAITED ${n} DAYS FOR A PASSING`, `PARTY TO TRADE YOU ONE (${f} LB OF FOOD).`].concat(d.map((x) => `${x} HAS DIED.`));
}
/** Today's event, if any (5.3): the chances are multiplied by the pace (a hard pace breaks things) and the rations. Applies it and returns
 * its lines, or null. */
function rollEvent(J) {
  const w = EVENT_RATE * (1 + 0.3 * J.pace);
  for (const [chance, when, act] of EVENTS) {
    if (when && !when(J)) continue;
    if (rnd(1) < chance * w) { const lines = act(J); J.log.push(lines.join(' ')); if (!alive(J).length) J.done = true; return lines; }
  }
  return null;
}
/** The chance a well person falls ill today: more with a hard pace, poor rations, poor health and cold. */
const illChance = (J, p, resting) => 0.006 * (1 + J.pace + J.rations + (p.health < 50 ? 2 : 0) + (COLD[J.weather] ? 1 : 0)) * (resting ? 0.5 : 1);
/** The score on arriving (5.6). */
function scoreOf(J) {
  const words = { GOOD: 4, FAIR: 3, POOR: 2, 'VERY POOR': 1 };
  let s = 0;
  for (const p of alive(J)) { const h = p.health >= 70 ? 4 : p.health >= 50 ? 3 : p.health >= 30 ? 2 : 1; s += 500 * h; }
  s += 50 + J.oxen * 4 + (J.wheel + J.axle + J.tongue) * 2 + J.clothes * 2 + Math.floor(J.bullets / 50) + Math.floor(J.food / 25) + Math.floor(J.money / 5);
  return s * BACKGROUNDS[J.bg].mult;
}
/** Crossing a river (5.4): what the depth does to a ford; the ferry; caulking and floating, by the float's hits. */
function crossRiver(J, how, river, hits = 0) {
  const d = riverDepth(J, river);
  if (how === 'guide') { if (J.clothes < 1) return 'NO CLOTHING TO TRADE FOR A GUIDE.'; J.clothes--; advanceDate(J); return 'A SHOSHONE GUIDE LED THE WAGON ACROSS BY THE SHALLOWS, SAFELY.'; }
  if (how === 'ferry') { const fee = river.ferry || 0; if (J.money < fee) return 'NO MONEY FOR THE FERRY'; J.money -= fee; advanceDate(J); return 'THE FERRY TOOK YOU ACROSS.'; }
  if (how === 'ford') {
    if (d < 2.5) return 'YOU FORDED THE RIVER SAFELY.';
    if (d < 3 && rnd(1) < 0.7) return 'YOU FORDED THE RIVER. IT WAS CLOSE.';
    return loseSupplies(J, d < 3 ? 0.2 : 0.4, 'THE WAGON TIPPED IN THE RIVER.');
  }
  return floatOutcome(J, hits, false);                              // caulk and float: what the float (its hits) did
}
/** What a float's hits do (5.4): none is safe; one loses some food; two lose a share of the goods; three or more swamp the wagon, and
 * someone may drown. The Columbia (big) is worse. */
function floatOutcome(J, hits, big) {
  if (!hits) return big ? 'YOU RAFTED DOWN THE COLUMBIA SAFELY.' : 'YOU FLOATED ACROSS SAFELY.';
  if (hits === 1) { const f = Math.floor(J.food * 0.08); J.food -= f; J.log.push(`THE WAGON STRUCK A ROCK. LOST ${f} LB OF FOOD.`); return `THE WAGON STRUCK A ROCK. LOST ${f} LB OF FOOD.`; }
  if (hits === 2) return loseSupplies(J, big ? 0.25 : 0.15, 'THE WAGON STRUCK ROCKS.');
  return loseSupplies(J, big ? 0.5 : 0.35, 'THE WAGON SWAMPED.');
}
function loseSupplies(J, share, what) {
  const lost = Math.floor(J.food * share); J.food -= lost; J.clothes -= Math.floor(J.clothes * share); J.bullets -= Math.floor(J.bullets * share);
  let t = `${what} LOST ${lost} LB OF FOOD`;
  if (rnd(1) < share) { const v = alive(J)[rndi(0, alive(J).length - 1)]; v.alive = false; t += `. ${v.name} DROWNED`; if (!alive(J).length) J.done = true; }
  J.log.push(t + '.');
  return t + '.';
}
/** The cost of buying n more of a good at a price multiplier (the forts': 5.1). */
const costOf = (g, n, mult = 1) => Math.round(g.price * n * mult * 100) / 100;

// --- The hunt (5.5): 30 seconds; animals of the region cross in three lanes at their own speeds; the d-pad aims, A fires a bullet. At most
// CARRY lb comes back, and the hunt takes a day. ---
const MEAT = { rabbit: 2, squirrel: 1, deer: 50, elk: 80, bear: 100, buffalo: 400 };
const SPEED = { rabbit: 1.5, squirrel: 1.2, deer: 1.1, elk: 0.85, bear: 0.6, buffalo: 0.5 };
const BIG = { deer: 1, elk: 1, bear: 1, buffalo: 1 };
const GAME = [                                                       // by region: [kind, how often]
  [['rabbit', 4], ['squirrel', 2], ['deer', 3], ['buffalo', 3]],     // the prairie
  [['rabbit', 4], ['deer', 3], ['buffalo', 3]],                      // the bluffs
  [['squirrel', 4], ['deer', 3], ['elk', 2], ['bear', 1]],           // the mountains
  [['rabbit', 5], ['deer', 3], ['elk', 1]],                          // the high desert
  [['squirrel', 4], ['deer', 3], ['elk', 2], ['bear', 1]],           // the forest
];
const HUNT_FRAMES = 1800, CARRY = 100, AIM_SPEED = 2, LANES = [124, 136, 149];   // the lanes' feet, far to near
let hunt = null;
function toHunt() {
  state = 'hunt'; timer = 0; card = null;
  hunt = { aim: [128, 96], animals: [], meat: 0, kills: 0, fired: 0, flash: 0, spawn: 20, pops: [] };
}
function pickGame(region) {
  const list = GAME[region], total = list.reduce((s, g) => s + g[1], 0);
  let r = rnd(total); for (const [k, w] of list) { if ((r -= w) < 0) return k; } return list[0][0];
}
/** An animal's box to hit (inside its picture). */
const animalBox = (a) => (BIG[a.kind] ? [a.x + 3, a.y + 4, 26, 20] : [a.x + 2, a.y + 6, 12, 10]);
function updateHunt() {
  const h = hunt, held = (b) => (inputMask & (1 << b)) !== 0;
  if (pressed(START)) { paused = true; pauseSel = 0; fx(SFX.pause); return; }
  if (held(LEFT)) h.aim[0] -= AIM_SPEED; if (held(RIGHT)) h.aim[0] += AIM_SPEED;
  if (held(UP)) h.aim[1] -= AIM_SPEED; if (held(DOWN)) h.aim[1] += AIM_SPEED;
  h.aim[0] = clamp(h.aim[0], 4, 251); h.aim[1] = clamp(h.aim[1], 60, 148);
  if (--h.spawn <= 0 && h.animals.filter((a) => !a.dead).length < 5) {
    const kind = pickGame(regionAt(J.mile)), lane = rndi(0, 2), dir = rnd(1) < 0.5 ? 1 : -1, w = BIG[kind] ? 32 : 16, hh = BIG[kind] ? 24 : 16;
    h.animals.push({ kind, x: dir > 0 ? -w : 256, y: LANES[lane] - hh, lane, w, h: hh, dir, v: SPEED[kind] * (0.85 + rnd(0.3)), dead: 0, t: 0 });
    h.animals.sort((a, b) => a.lane - b.lane);
    h.spawn = Math.round(rndi(35, 90) * (J.month <= 1 || J.month === 11 ? 1.6 : 1));   // fewer in winter
  }
  for (const a of h.animals) { a.t++; if (a.dead) a.dead++; else a.x += a.v * a.dir; }
  h.animals = h.animals.filter((a) => a.dead < 40 && a.x > -40 && a.x < 260);
  for (const p of h.pops) p.t++; h.pops = h.pops.filter((p) => p.t < 50);
  if (h.flash) h.flash--;
  if (pressed(A)) {
    if (J.bullets <= 0) fx(SFX.move);
    else {
      J.bullets--; h.fired++; h.flash = 5; fx(SFX.shot);
      const [x, y] = h.aim, hit = h.animals.slice().reverse().find((a) => { if (a.dead) return false; const [bx, by, bw, bh] = animalBox(a); return x >= bx && x < bx + bw && y >= by && y < by + bh; });
      if (hit) { hit.dead = 1; h.meat += MEAT[hit.kind]; h.kills++; h.pops.push({ x: hit.x + hit.w / 2, y: hit.y, n: MEAT[hit.kind], t: 0 }); fx(SFX.good); }
      else for (const a of h.animals) if (!a.dead && Math.abs(a.x + a.w / 2 - x) < 48) a.v *= 1.8;   // a miss startles those near it
    }
  }
  if (timer >= HUNT_FRAMES || (pressed(B) && timer > 20)) endHunt();
}
function endHunt() {
  const h = hunt, got = Math.min(h.meat, CARRY);
  J.food += got;
  const died = loseDays(J, 1);
  J.log.push(h.meat ? `HUNTED: ${h.meat} LB OF MEAT, ${got} LB CARRIED BACK.` : 'HUNTED, AND SHOT NOTHING.');
  toTrail(); hunt = null;
  const lines = h.meat ? [`YOU SHOT ${h.meat} LB OF MEAT.`].concat(h.meat > CARRY ? [`YOU CAN CARRY ONLY ${CARRY} LB`, 'BACK TO THE WAGON.'] : []) : ['YOU SHOT NOTHING.'];
  showCard('THE HUNT', lines.concat(died.map((n) => `${n} HAS DIED.`)), null, () => { if (J.done) endJourney(); });
}

// --- The float (5.4): the wagon, caulked, goes down the current from the bottom of the screen; rocks and eddies come at it; LEFT and RIGHT
// steer. Each rock struck is a hit; floatOutcome says what they cost. ---
const WATER = 115, WATER2 = 116, ROCK = 117, ROCK2 = 118, BANK = 119, BANK2 = 120, CANVAS = 121, WOOD = 122;
const FLOAT_Y = 136;
let flt = null;
/** A float: frames long, a rock every gap frames, the current's speed; then(hits) when it is over. */
function toFloat(title, frames, gap, current, then) {
  state = 'float'; timer = 0; card = null;
  flt = { title, frames, gap, current, then, x: 128, vx: 0, rocks: [], eddies: [], hits: 0, hurt: 0, dist: 0, spawn: 30, bump: 0 };
}
/** The banks at a screen line: [left edge of the water, right edge]. */
function banks(f, y) { const k = f.dist - y; return [26 + 12 * Math.sin(k / 47) + 6 * Math.sin(k / 13), 230 + 12 * Math.sin(k / 53 + 2) + 6 * Math.sin(k / 17)]; }
function updateFloat() {
  const f = flt, held = (b) => (inputMask & (1 << b)) !== 0;
  if (pressed(START)) { paused = true; pauseSel = 0; fx(SFX.pause); return; }
  if (held(LEFT)) f.vx -= 0.3; if (held(RIGHT)) f.vx += 0.3;
  if (!held(LEFT) && !held(RIGHT)) f.vx *= 0.88;
  for (const e of f.eddies) if (Math.abs(e.x - f.x) < e.r + 6 && Math.abs(e.y - FLOAT_Y) < e.r + 8) f.vx += 0.12 * e.s;
  f.vx = clamp(f.vx, -2.4, 2.4); f.x += f.vx;
  const [l, r] = banks(f, FLOAT_Y);
  if (f.x < l + 8 || f.x > r - 8) { f.x = clamp(f.x, l + 8, r - 8); f.vx = 0; if (!f.bump) { fx(SFX.move); f.bump = 20; } }
  if (f.bump) f.bump--;
  f.dist += f.current;
  for (const o of f.rocks) o.y += f.current; for (const e of f.eddies) e.y += f.current;
  f.rocks = f.rocks.filter((o) => o.y < 200); f.eddies = f.eddies.filter((e) => e.y < 200);
  if (--f.spawn <= 0 && timer < f.frames - 70) {
    const [bl, br] = banks(f, -12), rr = rndi(5, 9);
    if (rnd(1) < 0.8) f.rocks.push({ x: rndi(bl + rr + 4, br - rr - 4), y: -12, r: rr });
    else f.eddies.push({ x: rndi(bl + 20, br - 20), y: -14, r: 12, s: rnd(1) < 0.5 ? 1 : -1 });
    f.spawn = Math.round(f.gap * (0.6 + rnd(0.8)));
  }
  if (f.hurt) f.hurt--;
  else for (const o of f.rocks) if (!o.hit && Math.abs(o.x - f.x) < o.r + 5 && Math.abs(o.y - FLOAT_Y) < o.r + 9) { o.hit = true; f.hits++; f.hurt = 40; fx(SFX.splash); break; }
  if (timer >= f.frames) { const then = f.then, hits = f.hits; flt = null; toTrail(); then(hits); }
}

// --- Trading (5.5): a day spent waiting by the trail brings a trader: one of the region's people, or another traveller. Each offers one
// good for another, near its worth; accept or decline. ---
const TRADERS = [['A PAWNEE TRADER', 'A SETTLER'], ['A LAKOTA TRADER', 'A FRENCH TRAPPER'], ['A SHOSHONE TRADER', 'A MOUNTAIN MAN'], ['A SHOSHONE TRADER', 'A FAMILY GOING EAST'], ['A NEZ PERCE TRADER', 'A SETTLER']];
const WORTH = { oxen: 40, food: 0.2, clothes: 10, bullets: 0.1, wheel: 10, axle: 10, tongue: 10 };
const TRADE_LOTS = { oxen: [1, 1], food: [50, 150], clothes: [1, 3], bullets: [20, 60], wheel: [1, 1], axle: [1, 1], tongue: [1, 1] };
const TRADE_STEP = { food: 10, bullets: 10 };
function goodText(k, n) {
  if (k === 'oxen') return `${n} YOKE OF OXEN`;
  if (k === 'food') return `${n} LB OF FOOD`;
  if (k === 'clothes') return `${n} SET${n > 1 ? 'S' : ''} OF CLOTHING`;
  if (k === 'bullets') return `${n} BULLETS`;
  return n > 1 ? `${n} SPARE ${k.toUpperCase()}S` : `A SPARE ${k.toUpperCase()}`;
}
/** Today's offer, or null: { who, give: [good, n], want: [good, n] }, where want is something the party has. */
function tradeOffer(J) {
  const keys = Object.keys(WORTH), region = regionAt(J.mile);
  for (let tries = 0; tries < 12; tries++) {
    const give = keys[rndi(0, keys.length - 1)], want = keys[rndi(0, keys.length - 1)];
    if (give === want) continue;
    const [lo, hi] = TRADE_LOTS[give], step = TRADE_STEP[give] || 1, gn = Math.round(rndi(lo, hi) / step) * step;
    const ws = TRADE_STEP[want] || 1, wn = Math.max(ws, Math.round(gn * WORTH[give] * (0.9 + rnd(0.5)) / WORTH[want] / ws) * ws);
    const gw = WORTH[give] * gn, ww = WORTH[want] * wn;
    if (ww < gw * 0.8 || ww > gw * 1.6) continue;                  // near its worth (a little in the trader's favour)
    if (J[want] < wn + (want === 'oxen' ? 1 : 0)) continue;           // only what the party has, and never their last yoke
    const who = TRADERS[region][rnd(1) < 0.6 ? 0 : 1];
    return { who, give: [give, gn], want: [want, wn] };
  }
  return null;
}
function applyTrade(J, o) { J[o.want[0]] -= o.want[1]; J[o.give[0]] += o.give[1]; J.log.push(`TRADED ${goodText(...o.want)} FOR ${goodText(...o.give)}.`); }
/** The menu's TRADE: a day passes, then the offer (or nobody). */
function seekTrade() {
  const died = loseDays(J, 1), dl = died.map((n) => `${n} HAS DIED.`);
  if (J.done) return showCard(dateText(J), dl, null, endJourney);
  const o = rnd(1) < 0.85 ? tradeOffer(J) : null;
  if (!o) return showCard('TRADING', dl.concat(['NOBODY CAME BY TO TRADE TODAY.']));
  showCard('TRADING', dl.concat([`${o.who} OFFERS`, `${goodText(...o.give)}`, `FOR ${goodText(...o.want)}.`]), ['ACCEPT', 'DECLINE'], (c) => {
    if (c === 0) { applyTrade(J, o); fx(SFX.good); showCard('TRADING', ['IT IS A DEAL.', `+${goodText(...o.give)}`]); }
  });
  card.offer = o;
}

// --- Save slots (spec section 13; the journey's save comes in step 6) ---

const VERSION_SLOT = 0, SAVE_VERSION = 1, TOP_SLOT = 100, TOP_N = 10;
function topTen() { const out = []; for (let i = 0; i < TOP_N; i++) out.push({ score: dget(TOP_SLOT + i * 4), name: unpackName(dget(TOP_SLOT + i * 4 + 1), dget(TOP_SLOT + i * 4 + 2)), bg: dget(TOP_SLOT + i * 4 + 3) }); return out; }
function insertTop(e) {
  if (!e.score) return -1;
  const list = topTen(), at = list.findIndex((x) => e.score > x.score);
  if (at < 0) return -1;
  list.splice(at, 0, e);
  for (let i = at; i < TOP_N; i++) { const [a, b] = packName(list[i].name); dset(TOP_SLOT + i * 4, list[i].score); dset(TOP_SLOT + i * 4 + 1, a); dset(TOP_SLOT + i * 4 + 2, b); dset(TOP_SLOT + i * 4 + 3, list[i].bg); }
  return at;
}
const CHARS = ' ABCDEFGHIJKLMNOPQRSTUVWXYZ.-\'';
/** A name of up to 10 characters in two slots (5 bits each, 5 a slot... 6 in the first). */
function packName(s) { const v = [0, 0]; for (let i = 0; i < 10; i++) { const c = Math.max(0, CHARS.indexOf(s[i] || ' ')); v[i >> 1 > 2 ? 1 : 0] += 0; } let a = 0, b = 0; for (let i = 0; i < 5; i++) a = a * 32 + Math.max(0, CHARS.indexOf(s[i] || ' ')); for (let i = 5; i < 10; i++) b = b * 32 + Math.max(0, CHARS.indexOf(s[i] || ' ')); return [a, b]; }
function unpackName(a, b) { let s = ''; for (let i = 4; i >= 0; i--) s = CHARS[(a >> (5 * i)) & 31] + s; let t = ''; for (let i = 4; i >= 0; i--) t = CHARS[(b >> (5 * i)) & 31] + t; return (rev(s) + rev(t)).trim(); }
const rev = (s) => s.split('').reverse().join('');

// --- Input ---

let inputMask = 0, prevMask = 0;
const BUTTONS = [UP, DOWN, LEFT, RIGHT, A, B, X, Y, L, R, START, SELECT];
function readPad() { let m = 0; for (const b of BUTTONS) if (btn(b)) m |= 1 << b; return m; }
const pressed = (b) => (inputMask & (1 << b)) !== 0 && (prevMask & (1 << b)) === 0;
const stepped = (b) => pressed(b) || (btnp(b) && (inputMask & (1 << b)) !== 0);

// --- State ---

let skipTitle = false;                                              // tests set this to land straight on the trail with a stocked wagon
let state = 'title', paused = false, timer = 0, clock = 0, sel = 0, pauseSel = 0;
let J = null, setup = { bg: 0, month: 1, step: 0 }, cart = {}, storeMult = 1, card = null, dayTimer = 0, scroll = 0, rank = -1;
const DAY_FRAMES = 50;                                              // a day rolls by in this many frames (spec: about a second)
const NAMES = ['MARY', 'JOHN', 'SARAH', 'WILL', 'ELLA'];            // step 6 adds naming them

// --- The book (rom/book.bin, from book.py): each place's paragraph and its people, the regions' cards ---
let BOOK = null;
function loadBook() {
  const b = rom('book'); let i = 3;
  const str = () => { const n = b[i++]; let t = ''; for (let k = 0; k < n; k++) t += String.fromCharCode(b[i++]); return t; };
  const places = {}, regions = [];
  for (let n = b[i++]; n > 0; n--) { const name = str(), about = str().split('|'), talk = []; for (let t = b[i++]; t > 0; t--) talk.push({ who: str(), lines: str().split('|') }); places[name] = { about, talk }; }
  for (let n = b[i++]; n > 0; n--) regions.push({ name: str(), lines: str().split('|') });
  BOOK = { places, regions };
}

function init() {
  loadBook();
  if (dget(VERSION_SLOT) !== SAVE_VERSION) { for (let i = 0; i < 256; i++) dset(i, 0); dset(VERSION_SLOT, SAVE_VERSION); }
  for (const [layer, name] of [[0, 'ground'], [1, 'near'], [2, 'far']]) { const sc = ART.scenes[name]; bg(layer, { mx: sc.mx, my: sc.my, mw: sc.w, mh: sc.h, x: 0, y: 0, wrap: true, show: true }); }
  color(SOLID, 6, 4, 2); color(BOARD, 14, 9, 5);
  color(WATER, 6, 12, 18); color(WATER2, 14, 21, 26); color(ROCK, 10, 9, 9); color(ROCK2, 17, 16, 15); color(BANK, 9, 14, 6); color(BANK2, 20, 17, 10); color(CANVAS, 29, 28, 24); color(WOOD, 13, 8, 4);
  blend({ layers: ['overlay'], half: true });
  if (skipTitle) { J = newJourney(0, 3, NAMES); Object.assign(J, { departed: true, oxen: 4, food: 900, clothes: 10, bullets: 200, wheel: 1, axle: 1, tongue: 1, money: 1600 - 4 * 40 - 180 - 100 - 20 - 30 }); toTrail(); }
  else toTitle();
}

function toTitle() { state = 'title'; timer = 0; sel = 0; paused = false; play(SONG.title); }
function toSetup() { state = 'setup'; timer = 0; setup = { bg: 0, month: 1, step: 0 }; }
function toStore(mult = 1) { state = 'store'; timer = 0; sel = 0; storeMult = mult; cart = {}; for (const g of GOODS) cart[g.key] = 0; }
function toTrail() { state = 'trail'; timer = 0; paused = false; card = null; dayTimer = 0; play(SONG.trail); }
function toMenu() { state = 'menu'; timer = 0; sel = 0; }
/** A card over the trail: a title, lines, and choices (or none: A continues). then(choice) runs when one is made. */
function showCard(title, lines, choices = null, then = null) { card = { title, lines, choices, then, sel: 0 }; }

// --- Update ---

function update() {
  inputMask = readPad(); clock++;
  if (!paused) timer++;
  if (paused) updatePause();
  else if (card) updateCard();
  else if (state === 'title') updateTitle();
  else if (state === 'setup') updateSetup();
  else if (state === 'store') updateStore();
  else if (state === 'trail') updateTrail();
  else if (state === 'menu') updateMenu();
  else if (state === 'hunt') updateHunt();
  else if (state === 'float') updateFloat();
  else if (state === 'end') updateEnd();
  else if (state === 'records') { if (timer > 20 && (pressed(A) || pressed(B) || pressed(START))) toTitle(); }
  prevMask = inputMask;
}

function updateCard() {
  const c = card;
  if (c.choices) {
    if (stepped(UP)) { c.sel = (c.sel + c.choices.length - 1) % c.choices.length; fx(SFX.move); }
    if (stepped(DOWN)) { c.sel = (c.sel + 1) % c.choices.length; fx(SFX.move); }
    if (pressed(A)) { fx(SFX.select); card = null; if (c.then) c.then(c.sel); }
  } else if (pressed(A) || pressed(B)) { fx(SFX.select); card = null; if (c.then) c.then(0); }
}

function updateTitle() {
  scroll++;                                                        // the prairie drifts by behind the title
  if (stepped(UP) || stepped(DOWN)) { sel ^= 1; fx(SFX.move); }
  if (pressed(A) || pressed(START)) { fx(SFX.select); if (sel === 0) toSetup(); else { state = 'records'; timer = 0; } }
}

/** The setup (spec 10): the background, then the month; the names are fixed until step 6. */
function updateSetup() {
  if (setup.step === 0) {
    if (stepped(UP)) { setup.bg = (setup.bg + 2) % 3; fx(SFX.move); }
    if (stepped(DOWN)) { setup.bg = (setup.bg + 1) % 3; fx(SFX.move); }
  } else {
    if (stepped(UP)) { setup.month = (setup.month + 5) % 6; fx(SFX.move); }
    if (stepped(DOWN)) { setup.month = (setup.month + 1) % 6; fx(SFX.move); }
  }
  if (pressed(B)) { fx(SFX.move); if (setup.step) setup.step--; else toTitle(); }
  else if (pressed(A)) {
    fx(SFX.select);
    if (setup.step === 0) setup.step = 1;
    else { J = newJourney(setup.bg, START_MONTHS[setup.month], NAMES); toStore(); }
  }
}

/** The store (5.1): UP and DOWN choose a good, LEFT and RIGHT change how many to buy, A leaves (with at least a yoke of oxen at Independence). */
const cartCost = () => GOODS.reduce((s, g) => s + costOf(g, cart[g.key], storeMult), 0);
function updateStore() {
  const n = GOODS.length + 1;
  if (stepped(UP)) { sel = (sel + n - 1) % n; fx(SFX.move); }
  if (stepped(DOWN)) { sel = (sel + 1) % n; fx(SFX.move); }
  if (sel < GOODS.length) {
    const g = GOODS[sel], have = Math.ceil(J[g.key] / (g.per || 1)) + cart[g.key];
    if (stepped(RIGHT) && have + g.step <= g.max && cartCost() + costOf(g, g.step, storeMult) <= J.money + 1e-9) { cart[g.key] += g.step; fx(SFX.move); }
    if (stepped(LEFT) && cart[g.key] > 0) { cart[g.key] -= g.step; fx(SFX.move); }
  }
  if (pressed(A) && sel === GOODS.length || pressed(START)) {
    if (J.mile === 0 && J.oxen + cart.oxen < 1) { fx(SFX.bad); showCard('THE STORE', ['YOU NEED AT LEAST ONE YOKE', 'OF OXEN TO PULL THE WAGON.']); return; }
    J.money = Math.round((J.money - cartCost()) * 100) / 100;
    for (const g of GOODS) J[g.key] += cart[g.key] * (g.per || 1);
    fx(SFX.select); toTrail();
    if (!J.departed) { J.departed = true; showCard('INDEPENDENCE, MISSOURI', BOOK.places.INDEPENDENCE.about); }   // setting out
  } else if (pressed(B) && J.mile > 0) { fx(SFX.move); toTrail(); }
}

/** The trail: a day every DAY_FRAMES frames; A stops for the menu; landmarks and deaths stop the wagon with a card. */
function updateTrail() {
  if (pressed(START)) { paused = true; pauseSel = 0; fx(SFX.pause); return; }
  if (pressed(A)) { fx(SFX.select); toMenu(); return; }
  scroll += 1;
  if (++dayTimer < DAY_FRAMES) return;
  dayTimer = 0;
  travel(false);
}
/** A day's travel, then what it brings: deaths, illness, the landmark reached, the end. */
function travel(resting) {
  const out = dayOnTrail(J, resting), lines = [];
  for (const n of out.died) lines.push(`${n} HAS DIED.`);
  for (const t of out.ill) if (!out.died.some((n) => t.startsWith(n + ' '))) lines.push(t);   // the illness as it struck (it may have passed by the evening)
  const ev = !resting && out.arrived < 0 && !J.done ? rollEvent(J) : null;   // an event on a day of travel that reached no landmark
  const reg = regionAt(J.mile), newRegion = reg > J.region; J.region = Math.max(J.region, reg);
  const after = () => {
    if (J.done) return endJourney();
    const go = () => { if (out.arrived >= 0) reach(out.arrived); };
    if (newRegion) { const r = BOOK.regions[reg]; showCard(r.name, r.lines, null, go); } else go();   // a card on entering a new region
  };
  const evCard = () => { if (ev) { fx(/DIED|LOST|BROKE|THIEF|LAME|STORM|BLIZZARD|FIRE|BAD|ROUGH|LITTLE/.test(ev[0]) ? SFX.bad : SFX.good); showCard(dateText(J), ev, null, after); } else after(); };
  if (lines.length) { fx(out.died.length ? SFX.over : SFX.bad); showCard(dateText(J), lines, null, evCard); }
  else evCard();
  return out;
}
/** Reaching a landmark (5.3 to 5.4, 6): its scene and card, where you can look around (the book's paragraph), talk to the people there
 * (a different one each time) and, at a fort, buy supplies; then a river asks how to cross, a fork which way; the end ends. */
function reach(k) {
  const m = TRAIL[k]; J.next = k + 1; fx(SFX.good);
  J.log.push(`REACHED ${m.name}.`);
  if (m.kind === 'end') { J.arrived = true; J.done = true; return endJourney(); }
  showScene(m.name);                                                // its painted scene, when it has one (step 7 paints the rest)
  const page = BOOK.places[m.name], off = () => { sceneOn = -1; };
  const line = m.kind === 'river' ? `${m.width} FEET ACROSS, ${riverDepth(J, m).toFixed(1)} FEET DEEP.` : m.kind === 'fort' ? 'A FORT, WITH A STORE.' : m.kind === 'fork' ? 'THE TRAIL DIVIDES HERE.' : 'A LANDMARK ON THE TRAIL.';
  const look = () => showCard(m.name, page.about, null, arrive);
  const talk = () => {
    if (!page.talk.length) return showCard(m.name, ['NOBODY IS ABOUT.'], null, arrive);
    const n = J.talked[m.name] || 0, who = page.talk[n % page.talk.length]; J.talked[m.name] = n + 1;
    showCard(who.who, who.lines, null, arrive);
  };
  const onward = () => { off(); if (m.kind === 'river') crossing(m); else if (m.kind === 'fork') fork(m); };
  const opts = [['LOOK AROUND', look], ['TALK TO SOMEONE', talk]].concat(m.kind === 'fort' ? [['BUY SUPPLIES', () => { off(); toStore(m.prices); }]] : [])
    .concat([[m.kind === 'river' ? 'CROSS THE RIVER' : m.kind === 'fork' ? 'CHOOSE THE WAY' : 'GO ON', onward]]);
  const arrive = () => showCard(m.name, [line], opts.map((o) => o[0]), (c) => opts[c][1]());
  arrive();
}
const riverDepth = (J, m) => m.depth * (J.month >= 6 ? 0.7 : 1);    // lower water in late summer
/** A river's crossing (5.4): ford, float, the ferry, a guide where one offers, or wait a day. */
function crossing(m) {
  const ways = [['FORD THE RIVER', 'ford'], ['CAULK THE WAGON AND FLOAT', 'float']].concat(m.ferry ? [[`TAKE THE FERRY ($${m.ferry})`, 'ferry']] : [])
    .concat(m.guide ? [['HIRE A GUIDE (1 CLOTHING)', 'guide']] : []).concat([['WAIT A DAY', 'wait']]);
  const ask = () => showCard(m.name, [`${m.width} FEET ACROSS, ${riverDepth(J, m).toFixed(1)} FEET DEEP.`], ways.map((w) => w[0]), (c) => {
    const how = ways[c][1];
    if (how === 'wait') { dayOnTrail(J, true); return ask(); }
    const done = (r) => { fx(/LOST|DROWN|NO MONEY|NO CLOTHING/.test(r) ? SFX.bad : SFX.good); if (/^NO /.test(r)) return showCard(m.name, [r], null, ask); showCard(m.name, wrapText(r), null, () => { if (J.done) endJourney(); }); };
    if (how === 'float') return toFloat(m.name, clamp(Math.round(m.width * 0.6), 360, 660), Math.max(18, Math.round(40 - m.depth * 4)), 1.6 + m.depth * 0.1, (hits) => done(crossRiver(J, 'float', m, hits)));
    done(crossRiver(J, how, m));
  });
  ask();
}
/** A fork (5.3, 6): South Pass's two routes; at The Dalles the raft (a float down the Columbia) or the Barlow Road. */
function fork(m) {
  showCard(m.name, ['WHICH WAY?'], m.choices, (c) => {
    if (m.name === 'SOUTH PASS') J.route = c + 1;
    else if (c === 1) { J.money = Math.max(0, J.money - BARLOW_TOLL); for (let d = 0; d < BARLOW_DAYS; d++) dayOnTrail(J, true); J.log.push('TOOK THE BARLOW ROAD.'); }
    else { J.log.push('RAFTED DOWN THE COLUMBIA.'); toFloat('THE COLUMBIA RIVER', 1200, 18, 2.4, (hits) => { const r = floatOutcome(J, hits, true); fx(hits ? SFX.bad : SFX.good); showCard('THE COLUMBIA RIVER', wrapText(r), null, () => { if (J.done) endJourney(); }); }); }
  });
}
/** A text in lines of at most 28 letters (a card's width), broken at spaces. */
function wrapText(t, w = 28) {
  const out = []; let l = '';
  for (const word of t.split(' ')) { if (l && l.length + 1 + word.length > w) { out.push(l); l = word; } else l = l ? `${l} ${word}` : word; }
  if (l) out.push(l);
  return out;
}
function endJourney() {
  state = 'end'; timer = 0; card = null;
  const sc = J.arrived ? scoreOf(J) : 0;
  rank = J.arrived ? insertTop({ score: sc, name: J.party[0].name, bg: J.bg }) : -1;
  J.score = sc; fx(J.arrived ? SFX.record : SFX.over);
}
function updateEnd() { if (timer > 60 && (pressed(A) || pressed(START))) { fx(SFX.select); state = 'records'; timer = 0; } }

/** The menu (spec 4): continue, supplies, pace, rations, rest, hunt, trade. */
const MENU = ['CONTINUE ON THE TRAIL', 'CHECK SUPPLIES', 'CHANGE PACE', 'CHANGE RATIONS', 'STOP TO REST', 'HUNT FOR FOOD', 'TRADE'];
function updateMenu() {
  if (stepped(UP)) { sel = (sel + MENU.length - 1) % MENU.length; fx(SFX.move); }
  if (stepped(DOWN)) { sel = (sel + 1) % MENU.length; fx(SFX.move); }
  if (pressed(B)) { fx(SFX.move); toTrail(); return; }
  if (!pressed(A)) return;
  fx(SFX.select);
  if (sel === 0) toTrail();
  else if (sel === 1) showCard('SUPPLIES', supplyLines());
  else if (sel === 2) showCard('PACE', ['HOW FAST TO GO.'], PACES.map((p) => p.name), (c) => { J.pace = c; });
  else if (sel === 3) showCard('RATIONS', ['HOW MUCH TO EAT.'], RATIONS.map((r) => r.name), (c) => { J.rations = c; });
  else if (sel === 5) { if (J.bullets <= 0) showCard('THE HUNT', ['YOU HAVE NO BULLETS.']); else toHunt(); }
  else if (sel === 6) seekTrade();
  else showCard('REST', ['HOW MANY DAYS?'], ['1 DAY', '3 DAYS', '5 DAYS'], (c) => { const n = [1, 3, 5][c]; for (let d = 0; d < n && !J.done; d++) dayOnTrail(J, true); if (J.done) endJourney(); });
}
function supplyLines() {
  return [`OXEN: ${J.oxen} YOKE`, `FOOD: ${J.food} LB`, `CLOTHING: ${J.clothes} SETS`, `BULLETS: ${J.bullets}`, `WHEELS ${J.wheel}  AXLES ${J.axle}  TONGUES ${J.tongue}`, `MONEY: $${J.money.toFixed(2)}`];
}

function updatePause() {
  if (pressed(UP) || pressed(DOWN)) { pauseSel ^= 1; fx(SFX.move); }
  if (pressed(B) || (pressed(START) && pauseSel === 0) || (pressed(A) && pauseSel === 0)) { paused = false; fx(SFX.pause); }
  else if (pressed(A) || pressed(START)) { fx(SFX.select); toTitle(); }
}

// --- Draw ---

function draw() {
  cls();
  const trailOn = state === 'trail' || state === 'menu' || state === 'end' || state === 'title' || state === 'hunt';
  setLayers(trailOn);
  if (trailOn) weatherLook();
  if (trailOn && sceneOn < 0) { if (state !== 'hunt') drawWagon(); if (J && state !== 'title') drawWeather(); }
  if (trailOn && state !== 'title' && state !== 'hunt' && sceneOn < 0) drawHudBoard();
  if (state === 'title') drawTitle();
  else if (state === 'setup') drawSetup();
  else if (state === 'store') drawStore();
  else if (state === 'menu') drawMenu();
  else if (state === 'hunt') drawHunt();
  else if (state === 'float') drawFloat();
  else if (state === 'end') drawEnd();
  else if (state === 'records') drawRecords();
  if (card) drawCard();
  if (paused) drawPause();
}

/** The layers (spec 12): on the trail BG2 the far hills, BG1 the near, BG0 the ground, scrolled at their own speeds (parallax); on the
 * title BG2 is the logo; at a landmark with a scene, BG2 shows the scene (from the ROM) and the others hide. */
function setLayers(trailOn) {
  const lg = ART.scenes.logo, fr = ART.scenes.far;
  if (sceneOn >= 0) {
    bg(0, { show: false }); bg(1, { show: false });
    bg(2, { mx: SCENE_MAP[0], my: SCENE_MAP[1], mw: 32, mh: 19, x: 0, y: 0, wrap: false, show: true });
    return;
  }
  bg(0, { show: trailOn }); bg(1, { show: trailOn });
  if (state === 'title') bg(2, { mx: lg.mx, my: lg.my, mw: lg.w, mh: lg.h, x: 0, y: -24, wrap: false, show: true });
  else bg(2, { mx: fr.mx, my: fr.my, mw: fr.w, mh: fr.h, x: scroll >> 3, y: 0, wrap: true, show: trailOn });
  bgscroll(1, (scroll * 3) >> 3, 0); bgscroll(0, scroll, 0);
}
/** The wagon and the oxen: their frames go round while the wagon rolls. */
function drawWagon() {
  const rolling = state === 'trail' && !card && !paused, f = rolling ? (scroll >> 3) & 3 : 0;
  bigSprite(ART.big[ART.anims.wagon[f]], 92, 108, { prio: 3 });
  bigSprite(ART.big[ART.anims.oxen[rolling ? (scroll >> 2) & 3 : 0]], 144, 114, { prio: 3 });
}

// --- The landmark scenes (art.py: rom/scenes.bin): one at a time, its tiles into the reserved block from SCENE_BASE, its map into Map RAM
// at SCENE_MAP, its colours into BG palette 5. ---
const SCENE_BASE = 800, SCENE_MAP = [128, 32], SCENE_OF = { 'CHIMNEY ROCK': 0 };
let sceneOn = -1, sceneLoaded = -1;
function loadScene(k) {
  const b = rom('scenes'); let o = 1;
  for (let i = 0; i < k; i++) { const n = b[o + 30] | (b[o + 31] << 8); o += 32 + n * 32 + 32 * 19 * 2; }
  for (let i = 0; i < 15; i++) { const v = b[o + i * 2] | (b[o + i * 2 + 1] << 8); color(81 + i, v & 31, (v >> 5) & 31, v >> 10); }
  o += 30; const n = b[o] | (b[o + 1] << 8); o += 2;
  for (let t = 0; t < n; t++) {
    const tn = SCENE_BASE + t, x0 = (tn % 16) * 8, y0 = (tn >> 4) * 8;
    for (let y = 0; y < 8; y++) for (let x = 0; x < 8; x += 2) { const v = b[o++]; sset(x0 + x, y0 + y, v & 15); sset(x0 + x + 1, y0 + y, v >> 4); }
  }
  for (let i = 0; i < 32 * 19; i++) {
    const v = b[o + i * 2] | (b[o + i * 2 + 1] << 8), t = v & 1023;
    mset(SCENE_MAP[0] + (i % 32), SCENE_MAP[1] + ((i / 32) | 0), t ? tile(SCENE_BASE + t - 1, 5, !!(v & (1 << 13)), !!(v & (1 << 14))) : 0);
  }
  sceneLoaded = k;
}
function showScene(name) { const k = SCENE_OF[name]; if (k === undefined) return; if (sceneLoaded !== k) loadScene(k); sceneOn = k; }

// --- The weather you can see, and the season (spec 5.2): rain, snow and fog on the overlay, grey clouds and a dimmer sky in bad weather,
// the grass browning through the autumn. The colours are set from the art's own (kept at the start). ---
const FOG = 201, CLOUD0 = 52, GRASS0 = 17;
let baseCols = null, skyDim = 1;
function weatherLook() {
  if (!baseCols) { baseCols = {}; for (let e = 16; e < 64; e++) baseCols[e] = color(e); color(FOG, 26, 27, 28); }
  const w = J ? J.weather : 3, bad = w >= 6 && w <= 10;
  skyDim = w === 7 || w === 9 ? 0.6 : bad ? 0.8 : 1;
  for (let i = 0; i < 3; i++) { const v = baseCols[CLOUD0 + i], g = Math.round((v[0] + v[1] + v[2]) / 3 * 0.75); color(CLOUD0 + i, ...(bad ? [g, g, g + 1] : v)); }
  const m = J ? J.month : 4, autumn = clamp((m - 7) / 3, 0, 1), snow = w === 8 || w === 9 ? 0.5 : 0;   // September to November: towards straw
  for (let i = 0; i < 4; i++) { const v = baseCols[GRASS0 + i]; color(GRASS0 + i, ...v.map((c, k) => Math.round(lerp(lerp(c, [24, 20, 10][k] * (0.6 + 0.15 * i), autumn * 0.7), 28, snow)))); }
}
function drawWeather() {
  const w = J.weather;
  if (w === 6 || w === 7) for (let k = 0; k < (w === 7 ? 70 : 35); k++) { const x = (hash(k) + clock * 2) % 280 - 12, y = (hash(k * 7) + clock * 6) % 152; line(x, y, x - 2, y + 5, DIM); }
  if (w === 8 || w === 9) for (let k = 0; k < (w === 9 ? 80 : 40); k++) { const x = (hash(k) + clock + Math.round(3 * Math.sin((clock + k * 9) / 20))) % 256, y = (hash(k * 7) + clock) % 152; pset(x, y, WHITE); }
  if (w === 10) rectfill(0, 20, 256, 132, FOG);
}
const hash = (k) => (Math.imul(k + 1, 2654435761) >>> 0) % 997;

function drawHudBoard() {
  rectfill(0, 152, 256, 72, BOARD); for (let y = 160; y < 224; y += 16) line(0, y, 255, y, BROWN);
  rect(0, 152, 256, 72, 1); rectfill(0, 152, 256, 2, SOLID);
  const k = nextMark(J), to = markMile(J, k) - J.mile;
  txt(dateText(J), 8, 158, WHITE); txt(WEATHERS[J.weather], 248 - WEATHERS[J.weather].length * 8, 158, CYAN);
  txt(`HEALTH: ${healthWord(J)}`, 8, 172, healthWord(J) === 'GOOD' ? GREEN : healthWord(J) === 'FAIR' ? GOLD : RED);
  txt(`FOOD: ${J.food} LB`, 8, 184, J.food < 100 ? RED : WHITE);
  txt(`NEXT: ${TRAIL[k].name}`, 8, 196, WHITE); txt(`${to} MILES`, 8, 208, DIM);
  const tm = `${J.mile} MI`; txt(tm, 248 - tm.length * 8, 208, GOLD);
  txt(`${PACES[J.pace].name}`, 248 - PACES[J.pace].name.length * 8, 184, DIM);
  if (state === 'trail' && (clock >> 5) & 1) txt('A: STOP', 248 - 56, 196, DIM);
}

function drawTitle() {
  ['NEW JOURNEY', 'TOP 10'].forEach((s, i) => txt(`${i === sel ? '> ' : '  '}${s}`, 80, 168 + i * 14, i === sel ? WHITE : DIM));   // under the trail, clear of the wagon
}
function drawSetup() {
  panel(8, 16, 240, 192);
  ctxt(setup.step === 0 ? 'WHO LEADS THE PARTY?' : 'WHEN DO YOU SET OUT?', 26, GOLD);
  if (setup.step === 0) BACKGROUNDS.forEach((b, i) => { const y = 52 + i * 34, on = i === setup.bg; txt(`${on ? '>' : ' '} A ${b.name}`, 24, y, on ? WHITE : DIM); txt(`$${b.money}, ${b.gift}`, 40, y + 11, on ? GOLD : DIM); txt(`SCORE X${b.mult}`, 40, y + 21, DIM); });
  else START_MONTHS.forEach((m, i) => txt(`${i === setup.month ? '> ' : '  '}${MONTHS[m]}`, 72, 52 + i * 14, i === setup.month ? WHITE : DIM));
  ctxt('A: CHOOSE   B: BACK', 192, DIM);
}
function drawStore() {
  panel(4, 4, 248, 216);
  ctxt(J.mile === 0 ? 'THE STORE AT INDEPENDENCE' : `${TRAIL[J.next - 1].name}'S STORE`, 12, GOLD);
  GOODS.forEach((g, i) => {
    const y = 32 + i * 18, on = i === sel;
    txt(`${on ? '>' : ' '} ${g.name}`, 10, y, on ? WHITE : DIM);
    txt(`$${(g.price * storeMult).toFixed(2)} ${g.unit}`, 26, y + 9, DIM);
    const n = `${J[g.key] + cart[g.key] * (g.per || 1)}`; txt(n, 200 - n.length * 8, y, cart[g.key] ? GOLD : WHITE);
    if (on) txt('< >', 208, y, GOLD);
  });
  const y = 32 + GOODS.length * 18 + 4;
  txt(`${sel === GOODS.length ? '>' : ' '} LEAVE THE STORE`, 10, y, sel === GOODS.length ? WHITE : DIM);
  txt(`BILL $${cartCost().toFixed(2)}`, 10, 196, WHITE); const m = `YOU HAVE $${(J.money - cartCost()).toFixed(2)}`; txt(m, 246 - m.length * 8, 196, GOLD);
}
function drawMenu() {
  panel(16, 12, 224, 136);
  ctxt(`${TRAIL[nextMark(J)].name}: ${markMile(J, nextMark(J)) - J.mile} MI`, 20, GOLD);
  MENU.forEach((s, i) => txt(`${i === sel ? '> ' : '  '}${s}`, 28, 40 + i * 14, i === sel ? WHITE : DIM));
}
/** The hunt: the animals over the trail's layers, the aim, a flash for a shot, the meat rising from a kill; the board below. */
function drawHunt() {
  const h = hunt;
  for (const a of h.animals) {
    if (a.dead && (a.dead >> 2) & 1) continue;                   // a kill blinks out
    const f = a.dead ? 0 : (a.t >> (BIG[a.kind] ? 3 : 2)) & 1, flip = a.dir < 0;
    if (BIG[a.kind]) bigSprite(ART.big[ART.anims[a.kind][f]], Math.round(a.x), a.y, { fx: flip, prio: 3 });
    else sprite(ART.sprites[a.kind + f], Math.round(a.x), a.y, { fx: flip });
  }
  const [ax, ay] = h.aim;                                           // the aim, on the overlay above the animals
  for (const [c, o] of [[SHADOW, 1], [WHITE, 0]]) { line(ax - 7 + o, ay + o, ax - 3 + o, ay + o, c); line(ax + 3 + o, ay + o, ax + 7 + o, ay + o, c); line(ax + o, ay - 7 + o, ax + o, ay - 3 + o, c); line(ax + o, ay + 3 + o, ax + o, ay + 7 + o, c); }
  pset(ax, ay, RED);
  if (h.flash) circ(ax, ay, 9 - h.flash, GOLD);
  for (const p of h.pops) txt(`+${p.n}`, Math.round(p.x) - 8, Math.round(p.y - p.t / 3), GOLD);
  rectfill(0, 152, 256, 72, BOARD); for (let y = 160; y < 224; y += 16) line(0, y, 255, y, BROWN);
  rect(0, 152, 256, 72, 1); rectfill(0, 152, 256, 2, SOLID);
  const left = Math.max(0, Math.ceil((HUNT_FRAMES - timer) / 60));
  txt('THE HUNT', 8, 158, GOLD); const t = `TIME ${left}`; txt(t, 248 - t.length * 8, 158, left <= 5 ? RED : WHITE);
  txt(`MEAT: ${h.meat} LB`, 8, 174, h.meat > CARRY ? GOLD : WHITE); const b = `BULLETS: ${J.bullets}`; txt(b, 248 - b.length * 8, 174, J.bullets ? WHITE : RED);
  txt(`YOU CAN CARRY ${CARRY} LB BACK`, 8, 190, DIM);
  txt('A: SHOOT   B: STOP', 8, 206, DIM);
}
/** The float, from above, on the overlay: the water and its ripples, the banks, eddies, rocks, and the caulked wagon. */
function drawFloat() {
  const f = flt;
  rectfill(0, 0, 256, 152, WATER);
  for (let k = 0; k < 40; k++) { const x = hash(k) % 256, y = (hash(k * 5) + f.dist) % 160 - 4; line(x, y, x + 4 + (k & 3), y, WATER2); }
  for (let y = 0; y < 152; y += 2) { const [l, r] = banks(f, y); rectfill(0, y, Math.round(l), 2, BANK); rectfill(Math.round(r), y, 256, 2, BANK); rectfill(Math.round(l) - 3, y, 3, 2, BANK2); rectfill(Math.round(r), y, 3, 2, BANK2); }
  for (const e of f.eddies) { circ(Math.round(e.x), Math.round(e.y), e.r, WATER2); circ(Math.round(e.x), Math.round(e.y), e.r - 5, WATER2); }
  for (const o of f.rocks) { circfill(Math.round(o.x), Math.round(o.y), o.r, ROCK); circfill(Math.round(o.x) - 2, Math.round(o.y) - 2, o.r - 3, ROCK2); line(Math.round(o.x) - o.r, Math.round(o.y) + o.r - 1, Math.round(o.x) + o.r, Math.round(o.y) + o.r - 1, WATER2); }
  if (!(f.hurt && (f.hurt >> 2) & 1)) {
    const x = Math.round(f.x) - 6, y = FLOAT_Y - 10;
    rectfill(x - 1, y + 1, 14, 20, WOOD); rectfill(x + 1, y, 10, 20, CANVAS);
    for (let k = 3; k < 20; k += 5) line(x + 1, y + k, x + 10, y + k, BANK2);
    line(x + 2, y + 21 + (clock >> 3 & 1), x + 9, y + 21 + (clock >> 3 & 1), WATER2);   // the wake
  }
  rectfill(0, 152, 256, 72, BOARD); for (let y = 160; y < 224; y += 16) line(0, y, 255, y, BROWN);
  rect(0, 152, 256, 72, 1); rectfill(0, 152, 256, 2, SOLID);
  txt(f.title, 8, 158, GOLD);
  txt('ACROSS', 8, 176, DIM); rect(64, 176, 176, 8, BROWN); rectfill(65, 177, Math.round(174 * Math.min(1, timer / f.frames)), 6, CYAN);
  txt(`ROCKS STRUCK: ${f.hits}`, 8, 192, f.hits ? RED : WHITE);
  txt('LEFT/RIGHT: STEER', 8, 208, DIM);
}
function drawEnd() {
  panel(16, 24, 224, 120);
  if (J.arrived) {
    ctxt('YOU HAVE REACHED', 34, WHITE); ctxt('THE WILLAMETTE VALLEY!', 46, GOLD);
    ctxt(`${alive(J).length} OF 5 MADE IT, ${dateText(J)}`, 66, WHITE);
    ctxt(`SCORE ${J.score}`, 86, GOLD);
    if (rank >= 0) ctxt(`TOP 10: #${rank + 1}`, 100, CYAN);
  } else { ctxt('THE WHOLE PARTY', 50, WHITE); ctxt('HAS DIED ON THE TRAIL.', 62, RED); ctxt(`${J.mile} MILES FROM INDEPENDENCE`, 82, DIM); }
  if (timer > 60 && (clock >> 5) & 1) ctxt('A: CONTINUE', 124, DIM);
}
function drawRecords() {
  panel(16, 16, 224, 192);
  ctxt('TOP 10', 24, GOLD);
  topTen().forEach((e, i) => { const y = 44 + i * 14; txt(String(i + 1).padStart(2), 28, y, DIM); txt(e.score ? e.name : '---', 56, y, WHITE); if (e.score) { const s = String(e.score); txt(s, 228 - s.length * 8, y, GOLD); } });
}
function drawCard() {
  const c = card, h = 34 + c.lines.length * 11 + (c.choices ? c.choices.length * 12 + 6 : 12);
  const y0 = sceneOn >= 0 ? 224 - h - 4 : Math.max(4, 76 - (h >> 1));   // under a landmark's scene, at the foot of the screen
  panel(8, y0, 240, h);
  ctxt(c.title, y0 + 8, GOLD);
  c.lines.forEach((l, i) => ctxt(l, y0 + 24 + i * 11, WHITE));
  const yc = y0 + 28 + c.lines.length * 11;
  if (c.choices) c.choices.forEach((s, i) => txt(`${i === c.sel ? '> ' : '  '}${s}`, 20, yc + i * 12, i === c.sel ? WHITE : DIM));
  else if ((clock >> 4) & 1) ctxt('A', yc, DIM);
}
function drawPause() {
  panel(56, 80, 144, 48);
  ctxt('PAUSED', 88, GOLD);
  ['RESUME', 'QUIT TO TITLE'].forEach((s, i) => txt(`${i === pauseSel ? '>' : ' '} ${s}`, 68, 104 + i * 11, i === pauseSel ? WHITE : DIM));
}

function panel(x, y, w, h) { rectfill(x, y, w, h, SOLID); rect(x, y, w, h, GOLD); rect(x + 2, y + 2, w - 4, h - 4, BROWN); }
function txt(s, x, y, c) { print(s, x + 1, y + 1, SHADOW); print(s, x, y, c); }
const ctxt = (s, y, c) => txt(s, 128 - s.length * 4, y, c);

/** Each line of the screen: the sky's colour (the SNES did its skies this way, with HDMA). */
function scanline(y) {
  const v = ART.gradients.sky.lines[y];
  if (v !== undefined) color(0, flr((v & 31) * skyDim), flr(((v >> 5) & 31) * skyDim), flr((v >> 10) * skyDim));   // dimmer under rain and snow
}
